from collections import defaultdict

def find(parent, i):
    if parent[i] != i:
        parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX == rootY:
        return
    if rank[rootX] < rank[rootY]:
        parent[rootX] = rootY
    else:
        parent[rootY] = rootX
        if rank[rootX] == rank[rootY]:
            rank[rootX] += 1

def solve(N, p):
    parent = {i: i for i in range(N+1)}
    rank = {i: 0 for i in range(N+1)}
    marbles = [0] * (N + 2)
    visited = [0] * (N + 1)
    marbles[0] = 1
    q = []

    for i, p2 in enumerate(p):
        if visited[p2] == 0:
            q.append((i, 1))
            visited[p2] = 1
            marbles[p2] += marbles[i]

    while q:
        i, m = q.pop()
        union(parent, rank, i, p2)
        if visited[p2] == 0:
            q.append((p2, 1))
            visited[p2] = 1
            marbles[p2] += m

    ans = 0
    for i in range(1, N + 1):
        if visited[i]:
            continue
        if marbles[0] % 2 == 0:
            ans += marbles[i] - 1
        else:
            ans += marbles[i]
        ans %= 1000000007
    return ans

