            continue

        freqs = defaultdict(int)
        for i in range(N):
            freqs[i] = remembered.count(i)

        remaining = set()
        inconsistency = False
        for i in range(N):
            if A[i] == -1:
                for j in range(min(freqs[i], N) + 1, N + 1):
                    if j-1 < len(remembered) and remembered[j-1] > j - 1:
                        if remaining and remaining & (1 << (j-1)):
                            inconsistency = True
                            break
                        freqs[i] += 1
                        if i == missing - 1:
                            remaining |= (1 << (j-1))
                        else:
                            freqs[i] -= 1

        if inconsistency:
            results.append("impossible")
        else:
            S = [0] * N
            if remaining:
                bit = 0
                for i in range(1, N + 1):
                    if (remaining & 1) > 0:
                        S[i % 3] = bit
                        bit ^= 1
                    elif bit:
