from collections import defaultdict
import sys

def construct_tree(restored_distances, n):
    """
    Constructs the original tree based on the restored distances.

    :param restored_distances: A list where dist[i][j] represents the distance from vertex i to vertex j.
    :param n: The number of vertices.
    :return: A list of lists representing the edges of the tree, or -1 if no valid tree exists.
    """
    if n < 2 or not restored_distances:
        return [-1]  # No tree can have less than 2 vertices

    min_distances = defaultdict(lambda: sys.maxsize)
    for i in range(n):
        for j in range(n):
            if i != j:
                min_distances[i, j] = min(min_distances[i, j], restored_distances[i][j])

    def dfs(current, parent):
        for neighbor in range(n):
            if dist[current][neighbor] == min_distances[current, neighbor]:
                if parent == -1:
                    parent = neighbor
                else:
                    # parent connnected to index parent not child index parent index
                    adj.add((parent, neighbor))
                yield neighbor
                for nxt in dfs(neighbor, -1):
                    yield nxt

    parent = -1
    for a in sorted(min_distances.keys(), key=lambda i: (i[0], -i[1])):
        for b in sorted(min_distances[a], key=lambda i: (i, -a)):
            if a == b:
                continue
            dist = [[sys.maxsize] * n for _ in range(n)]
            parent = -1
            for c in dfs(a, parent):
                dist[a][c] = dist[c][a] = 1
                for d in dfs(c, -1):
                    dist[a][d] = 1
                    dist[d][a] = 1
            possible_tree = True
            for i, row in enumerate(dist):
                if i > 0:
                    possible_tree &= all(row[j] == dist[i-1][j] + 1 for j in range(n))
                if i < n-1 and dist[i][i+1] != 0 and dist[i][i-1] != 0 and dist[i][i+1] != dist[i][i-1]:
                    possible_tree &= all(dist[i][j] == dist[i+1][j-1] for j in range(i+1, n))
            if possible_tree:
                return [(a, b)]
    return [-1]

def reconstruct_tree(n, k, distances):
    # Construct the tree from the remembered distances
    restored_tree = construct_tree(distances, n)
    if restored_tree == [-1]:
        return "-" * n

    # Convert restored_tree back to strings and return edges
    restored_refs = [list(zip(*r)) for r in restored_tree]
    return [' '.join(map(str, r)) + ' ' for r in restored_refs]

