def count_max_sequences(n, m, k):
    if n > m:
        return count_max_sequences(m, n, k)
    result = 1
    power_sum = 0
    K = k * (m + n)
    MOD = 10**9 + 7

    for i in range(1, m + 1):
        power = 0
        for j in range(m - i + 1):
            if i * j <= m * (m + i - 1) // 2:
                power += 1
        power_sum += power
        power_sum %= MOD
        power = pow(2, (2 * j) - i + (i + j - 3) * (2 * m + 1) + 2 * j - 1, MOD - 1)
        result = (result * power) % MOD
        result %= MOD
    return result * factorials[K] % MOD

def factorial_mod(n, MOD):
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % MOD
    return result

def count_sequences_of_a_matrix(n, m, k):
    result = 0
    for length in range(1, n + m + 1):
        a, b = divmod(length, n)
        result += (2 ** (n - 1 - a) - 1) * pow(2, b, MOD - 1)
    return result % (MOD - 1)

T = int(input())
for _ in range(T):
    N, M, K = map(int, input().split())
    factorials = [1]
    for i in range(1, N):
