import heapq
from collections import defaultdict

def buildGraph():
    # Build the graph using the input edge data
    graph = defaultdict(dict)
    for x, y, wt in data[2:]:
        graph[x][y] = min(wt, graph.get(x, {}).get(y, float('inf')))
        graph[y][x] = wt
    return graph

def dijkstra(graph, src):
    shortest_paths = defaultdict(lambda: float('inf'))
    shortest_paths[src] = 0
    heap = [(0, src)]

    while heap:
        current_path_length, node = heapq.heappop(heap)
        if shortest_paths[node] != current_path_length:
            continue
        for neighbor, weight in graph.get(node, {}).items():
            distance = current_path_length + weight
            if distance < shortest_paths[neighbor]:
                shortest_paths[neighbor] = distance
                heapq.heappush(heap, (distance, neighbor))

    return shortest_paths

def processQuery3(graph, query):
    x, y = query[1:]
    path_len = float('inf')
    for neighbor, edge_len in graph.get(x, {}).items():
        if neighbor == y:
            path_len = min(path_len, edge_len)
    for neighbor, edge_len in graph.get(y, {}).items():
        if neighbor == x:
            path_len = min(path_len, edge_len)
    return path_len

