from collections import defaultdict

def restore_tree(n, k, distances):
    graph = defaultdict(list)
    degree = [0] * (n + 1)
    visited = [False] * (n + 1)

    for i in range(k):
        distances_ij = list(map(int, input().split()))
        for j in range(1, n + 1):
            graph[j].append(distances_ij[j - 1])
            degree[j] += 1

    for v in range(1, n + 1):
        if degree[v] != 2 * (n - 1):
            return -1

    for v in range(1, n + 1):
        edges = []
        for neighbor in graph[v]:
            if visited[neighbor]:
                continue
            visited[neighbor] = True
            neighbors_with_distance = [(i, neighbor, d) for i, d in enumerate(graph[neighbor])]
            neighbors_with_distance.sort(key=lambda x: x[1] * 2 + x[2])
            for i, ni, nd in neighbors_with_distance:
                if i < n:
                    continue
                if i == v:
                    continue
                edges.append((i, i - 1))
            break

    return min(edges) if edges else [-1]

